    reg [63:0] ssi_key_reg;
    reg [31:0] ssi_root_reg;
    reg [31:0] ssi_result_reg;

    reg [63:0] ranker_hash_reg;
    reg [63:0] ranker_seg_reg;
    reg [63:0] ranker_pos_reg;
    reg [31:0] ranker_score_reg;
    reg [31:0] ranker_result_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            axi_wr_state <= AXI_IDLE;
            axi_awready_reg <= 1'b0;
            axi_wready_reg <= 1'b0;
            axi_bvalid_reg <= 1'b0;
            axi_bresp_reg <= 2'b00;
            wr_addr_reg <= 16'h0000;
            control_reg <= 32'h00000000;
            config_reg <= 32'h00000000;
            ssi_key_reg <= 64'h0000000000000000;
            ssi_root_reg <= 32'h00000000;
            ranker_hash_reg <= 64'h0000000000000000;
            ranker_seg_reg <= 64'h0000000000000000;
            ranker_pos_reg <= 64'h0000000000000000;
            ranker_score_reg <= 32'h00000000;
        end else begin
            case (axi_wr_state)
