                    axi_bvalid_reg <= 1'b0;
                    axi_awready_reg <= 1'b0;
                    axi_wready_reg <= 1'b0;
                    if (axi_awvalid && axi_wvalid) begin
                        axi_awready_reg <= 1'b1;
                        axi_wready_reg <= 1'b1;
                        wr_addr_reg <= axi_awaddr;
                        axi_wr_state <= AXI_DATA;
                    end
