                    ADDR_RNK_HASH_L:  rd_data_reg <= ranker_hash_reg[31:0];
                    ADDR_RNK_HASH_H:  rd_data_reg <= ranker_hash_reg[63:32];
                    ADDR_RNK_SEG_L:   rd_data_reg <= ranker_seg_reg[31:0];
                    ADDR_RNK_SEG_H:   rd_data_reg <= ranker_seg_reg[63:32];
                    ADDR_RNK_POS_L:   rd_data_reg <= ranker_pos_reg[31:0];
                    ADDR_RNK_POS_H:   rd_data_reg <= ranker_pos_reg[63:32];
                    ADDR_RNK_SCORE:   rd_data_reg <= ranker_score_reg;
                    ADDR_RNK_RES:     rd_data_reg <= ranker_result_reg;
                    default:          rd_data_reg <= 32'hDEADBEEF;
                endcase
                axi_rresp_reg  <= 2'b00;
                axi_rvalid_reg <= 1'b1;
            end else if (axi_rvalid_reg && axi_rready) begin
                axi_rvalid_reg <= 1'b0;
            end
        end
    end

    assign ssi_search_key = ssi_key_reg;
    assign ssi_root_addr  = ssi_root_reg;
    assign ssi_start      = control_reg[0];

    assign ranker_query_hash  = ranker_hash_reg;
    assign ranker_segment_id  = ranker_seg_reg;
    assign ranker_segment_pos = ranker_pos_reg;
    assign ranker_base_score  = ranker_score_reg;
    assign ranker_valid       = control_reg[1];

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ssi_result_reg    <= 32'h00000000;
            ranker_result_reg <= 32'h00000000;
            status_reg        <= 32'h00000000;
            result_reg        <= 32'h00000000;
        end else begin
            if (ssi_done) begin
                ssi_result_reg   <= ssi_result_addr;
                status_reg[0]    <= ssi_found;
                status_reg[7:1]  <= 7'b0000000;
                status_reg[15:8] <= ssi_depth;
                result_reg       <= ssi_result_addr;
            end
            if (ranker_done) begin
                ranker_result_reg   <= ranker_final_score;
                status_reg[1]       <= 1'b1;
                status_reg[31:16]   <= ranker_rank;
                result_reg          <= ranker_final_score;
            end
        end
    end

    assign client_req[0] = ssi_start;
    assign client_req[1] = ranker_valid;
    assign client_req[2] = 1'b0;
    assign client_req[3] = 1'b0;

    SSISearch_topEntity ssi_search (
        .clk(clk),
        .rst(reset),
        .enable(1'b1),
        .searchRequest_key(ssi_search_key),
        .searchRequest_root(ssi_root_addr),
        .searchRequest_valid(ssi_start),
        .nodeData(mem_rdata),
        .nodeValid(mem_ready),
        .memAddr(ssi_mem_addr),
        .resultAddr(ssi_result_addr),
        .resultFound(ssi_found),
        .resultDepth(ssi_depth),
        .resultValid(ssi_done)
    );

    RankerCore_topEntity ranker (
        .clk(clk),
        .rst(reset),
        .enable(1'b1),
        .queryHash(ranker_query_hash),
        .segmentID(ranker_segment_id),
        .segmentPos(ranker_segment_pos),
        .baseScore(ranker_base_score),
        .inputValid(ranker_valid),
        .finalScore(ranker_final_score),
        .rank(ranker_rank),
        .outputValid(ranker_done)
    );

    MemoryArbiter_topEntity mem_arbiter (
        .clk(clk),
        .rst(reset),
        .enable(1'b1),
        .client0_req(client_req[0]),
        .client0_addr(ssi_mem_addr),
        .client1_req(client_req[1]),
        .client2_req(client_req[2]),
        .client3_req(client_req[3]),
        .client0_grant(client_grant[0]),
        .client1_grant(client_grant[1]),
        .client2_grant(client_grant[2]),
        .client3_grant(client_grant[3]),
        .memAddr(arbiter_mem_addr),
        .memWData(arbiter_mem_wdata),
        .memWE(arbiter_mem_we),
        .memReq(arbiter_mem_req)
    );

    assign mem_addr  = arbiter_mem_addr;
    assign mem_wdata = arbiter_mem_wdata;
    assign mem_we    = arbiter_mem_we;
    assign mem_oe    = !arbiter_mem_we && arbiter_mem_req;
    assign mem_ce    = arbiter_mem_req;

    assign led_status = {ssi_done, ranker_done, arbiter_mem_req, mem_ready, client_grant[3:0]};
    assign led_error  = (status_reg[0] == 1'b0) && ssi_done;
    assign irq_out    = ssi_done || ranker_done;

endmodule

module SSISearch_topEntity (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [63:0] searchRequest_key,
    input wire [31:0] searchRequest_root,
    input wire searchRequest_valid,
    input wire [15:0] nodeData,
    input wire nodeValid,
    output reg [31:0] memAddr,
    output reg [31:0] resultAddr,
    output reg resultFound,
    output reg [7:0] resultDepth,
    output reg resultValid
);

    reg [1:0] state;
    localparam S_IDLE = 2'b00;
    localparam S_READ = 2'b01;
    localparam S_DONE = 2'b10;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state       <= S_IDLE;
            memAddr     <= 32'h00000000;
            resultAddr  <= 32'h00000000;
            resultFound <= 1'b0;
            resultDepth <= 8'h00;
            resultValid <= 1'b0;
        end else begin
            if (!enable) begin
                state       <= S_IDLE;
                resultValid <= 1'b0;
            end else begin
                case (state)
                    S_IDLE: begin
                        resultValid <= 1'b0;
                        if (searchRequest_valid) begin
                            memAddr <= searchRequest_root ^ searchRequest_key[31:0];
                            state   <= S_READ;
                        end
                    end
                    S_READ: begin
                        if (nodeValid) begin
                            resultAddr  <= memAddr;
                            resultFound <= (nodeData != 16'h0000);
                            resultDepth <= 8'h01;
                            resultValid <= 1'b1;
                            state       <= S_DONE;
                        end
                    end
                    S_DONE: begin
                        resultValid <= 1'b0;
                        if (!searchRequest_valid) begin
                            state <= S_IDLE;
                        end
                    end
                    default: begin
                        state <= S_IDLE;
                    end
                endcase
            end
        end
    end

endmodule

module RankerCore_topEntity (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [63:0] queryHash,
    input wire [63:0] segmentID,
    input wire [63:0] segmentPos,
    input wire [31:0] baseScore,
    input wire inputValid,
    output reg [31:0] finalScore,
    output reg [15:0] rank,
    output reg outputValid
);

    reg busy;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            finalScore  <= 32'h00000000;
            rank        <= 16'h0000;
            outputValid <= 1'b0;
            busy        <= 1'b0;
        end else begin
            if (!enable) begin
                outputValid <= 1'b0;
                busy        <= 1'b0;
            end else begin
                if (inputValid && !busy) begin
                    finalScore  <= baseScore + queryHash[15:0] + segmentID[15:0] + segmentPos[15:0];
                    rank        <= 16'h0001;
                    outputValid <= 1'b1;
                    busy        <= 1'b1;
                end else begin
                    outputValid <= 1'b0;
                    if (!inputValid) begin
                        busy <= 1'b0;
                    end
                end
            end
        end
    end

endmodule

module MemoryArbiter_topEntity (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire client0_req,
    input wire [31:0] client0_addr,
    input wire client1_req,
    input wire client2_req,
    input wire client3_req,
    output reg client0_grant,
    output reg client1_grant,
    output reg client2_grant,
    output reg client3_grant,
    output reg [31:0] memAddr,
    output reg [15:0] memWData,
    output reg memWE,
    output reg memReq
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            client0_grant <= 1'b0;
            client1_grant <= 1'b0;
            client2_grant <= 1'b0;
            client3_grant <= 1'b0;
            memAddr       <= 32'h00000000;
            memWData      <= 16'h0000;
            memWE         <= 1'b0;
            memReq        <= 1'b0;
        end else begin
            if (!enable) begin
                client0_grant <= 1'b0;
                client1_grant <= 1'b0;
                client2_grant <= 1'b0;
                client3_grant <= 1'b0;
                memReq        <= 1'b0;
                memWE         <= 1'b0;
            end else begin
                client0_grant <= 1'b0;
                client1_grant <= 1'b0;
                client2_grant <= 1'b0;
                client3_grant <= 1'b0;
                memWE         <= 1'b0;
                memWData      <= 16'h0000;
                if (client0_req) begin
                    client0_grant <= 1'b1;
                    memAddr       <= client0_addr;
                    memReq        <= 1'b1;
                end else if (client1_req) begin
                    client1_grant <= 1'b1;
                    memReq        <= 1'b1;
                end else if (client2_req) begin
                    client2_grant <= 1'b1;
                    memReq        <= 1'b1;
                end else if (client3_req) begin
                    client3_grant <= 1'b1;
                    memReq        <= 1'b1;
                end else begin
                    memReq <= 1'b0;
                end
            end
        end
    end

endmodule
